<!--
 * 流程任务（列表页）
 *
 * @path apps\workflow-web\src\views\task\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 流程任务（列表页）
 * <p>消费后端契约 FlowTaskController（src/api/flowTask.ts，auto-generated by bash/gen-contract.py）：
 * 待办 todo() / 已办 done() 双 Tab（PageResponse 转 { items, total }），
 * 待办行通过「处理」弹窗（同意/驳回/转办/委托，见 task-form.vue），
 * 工具栏支持批量通过 batchPass / 批量驳回 batchReject。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { Page, useYdModal } from '@ydsz/common-ui';
import { YdBadge, YdButtonBase, YdTabs, YdTabsContent } from '@ydsz-core/ydsz-ui';
import { ydszPrompt } from '@ydsz-core/popup-ui';
import { h, ref } from 'vue';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { batchPass, batchReject, batchTransfer, batchUrge, done, todo } from '#/api/flowTask';
import type { FlowRunTaskVO } from '#/api/models';
import { $t } from '#/locales';
import { createLogger } from '@ydsz-core/shared/utils';
import TaskForm from './task-form.vue';

const logger = createLogger('workflow-task');
import TaskOperationDialog from './components/TaskOperationDialog.vue';
defineOptions({ name: 'TaskManagement' });

/** 当前 Tab：todo=待办，done=已办 */
const activeTab = ref<'todo' | 'done'>('todo');

/** 任务状态标签（兼容字符串/数字取值，未知值按原始值展示） */
function statusTag(taskStatus: string | undefined) {
  const status = (taskStatus ?? '').toUpperCase();
  if (status === 'DONE' || status === 'FINISHED' || status === 'COMPLETED' || status === '1') {
    return h(YdBadge, { variant: 'default' }, () => $t('wf.statusDone'));
  }
  if (status === 'REJECTED') {
    return h(YdBadge, { variant: 'destructive' }, () => $t('wf.statusRejected'));
  }
  if (status === 'DELEGATED' || status === 'TRANSFERRED') {
    return h(YdBadge, { variant: 'destructive' }, () => $t('wf.statusTransferred'));
  }
  if (status === 'SUSPENDED' || status === 'PAUSED') {
    return h(YdBadge, { variant: 'destructive' }, () => $t('wf.statusPaused'));
  }
  return h(YdBadge, { variant: 'default' }, () => taskStatus ?? '-');
}

const gridOptions: VxeTableGridOptions<FlowRunTaskVO> = {
  columns: [
    { type: 'checkbox', width: 50 },
    { type: 'seq', width: 50, title: $t('wf.seq') },
    { field: 'nodeName', title: $t('wf.taskNode'), width: 140 },
    { field: 'flowName', title: $t('wf.flowName'), width: 180 },
    { field: 'title', title: $t('wf.title'), width: 160 },
    { field: 'instanceId', title: $t('wf.instanceId'), width: 200 },
    { field: 'assigneeName', title: $t('wf.assignee'), width: 100 },
    {
      field: 'taskStatus',
      title: $t('wf.status'),
      width: 90,
      slots: { default: ({ row }) => statusTag(row.taskStatus) },
    },
    { field: 'createAt', title: $t('wf.createTime'), width: 170 },
    { field: 'dueAt', title: $t('wf.dueTime'), width: 170 },
    {
      field: 'action',
      title: $t('wf.action'),
      width: 120,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          // 已办列表不提供处理操作
          if (activeTab.value !== 'todo') return h('span', { class: 'text-gray-400 text-xs' }, '-');
          return h('div', { class: 'flex gap-1' }, [
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleProcess(row) },
              () => $t('wf.process'),
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link' as const, class: 'text-yellow-600', onClick: () => handleOperation(row) },
              () => '更多',
            ),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  checkboxConfig: { highlight: true },
  proxyConfig: {
    ajax: {
      query: async ({ page }, formValues) => {
        const params = {
          page: page.currentPage,
          size: page.pageSize,
          flowCode: formValues.flowCode,
          businessType: formValues.businessType,
        };
        const res = activeTab.value === 'todo' ? await todo(params) : await done(params);
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'flowCode',
        title: $t('wf.flowCode'),
        itemRender: { name: 'YdInput', props: { placeholder: $t('wf.flowCode') } },
      },
      {
        field: 'businessType',
        title: $t('wf.businessType'),
        itemRender: { name: 'YdInput', props: { placeholder: $t('wf.businessType') } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [TaskFormModal, taskFormApi] = useYdModal({ connectedComponent: TaskForm });
const [TaskOperationModal, taskOperationApi] = useYdModal({
  connectedComponent: TaskOperationDialog,
});

/** 切换待办/已办 Tab 后重新查询 */
function handleTabChange() {
  gridApi.query();
}

/** 打开任务处理弹窗 */
function handleProcess(row: FlowRunTaskVO) {
  taskFormApi.setData({ record: row });
  taskFormApi.open();
}

/** 打开任务操作弹窗（跳转/沟通/草稿） */
function handleOperation(row: FlowRunTaskVO) {
  taskOperationApi.setData({ task: row });
  taskOperationApi.open();
}

/** 收集勾选行的任务 ID，未勾选时提示 */
function getSelectedIds(): string[] {
  const rows = gridApi.grid.getCheckboxRecords() as FlowRunTaskVO[];
  const ids = rows.map((item) => item.id ?? '').filter((id) => id !== '');
  if (ids.length === 0) {
    showToast.warning($t('wf.selectTasksFirst'));
  }
  return ids;
}

/**
 * 批量通过勾选的任务。
 */
async function handleBatchPass() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      $t('wf.confirmBatchPass', { count: ids.length }),
      $t('wf.batchPassConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消批量通过操作', error);
    return; // 用户主动取消批量通过
  }
  // 步骤2：执行批量通过 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await batchPass(ids);
    showToast.success($t('wf.batchPassSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('批量通过失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/**
 * 批量驳回勾选的任务。
 */
async function handleBatchReject() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      $t('wf.confirmBatchReject', { count: ids.length }),
      $t('wf.batchRejectConfirm'),
      {
        type: 'warning',
        confirmButtonText: $t('wf.confirmReject'),
        cancelButtonText: $t('wf.cancel'),
      },
    );
  } catch (error) {
    logger.warn('用户取消批量驳回操作', error);
    return; // 用户主动取消批量驳回
  }
  // 步骤2：执行批量驳回 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await batchReject(ids.map((taskId) => ({ taskId })));
    showToast.success($t('wf.batchRejectSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('批量驳回失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/**
 * 批量转交勾选的任务。
 * 步骤1：弹窗让用户填写目标用户 ID 和转交意见；步骤2：调用后端 batchTransfer 端点。
 */
async function handleBatchTransfer() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  // 步骤1：输入弹窗获取目标用户和意见
  let targetUserId: string;
  let comment: string;
  try {
    const inputUserId = await ydszPrompt<string>({
      content: $t('wf.targetUser'),
      confirmText: $t('wf.confirm'),
      cancelText: $t('wf.cancel'),
      defaultValue: '',
      componentProps: {
        placeholder: $t('wf.targetUserPlaceholder'),
      },
      beforeClose: ({ isConfirm, value }) => {
        if (!isConfirm) return;
        if (!value) {
          showToast.warning($t('wf.fillTargetUser'));
          return false;
        }
      },
    });
    targetUserId = inputUserId ?? '';
    const inputComment = await ydszPrompt<string>({
      content: $t('wf.commentPlaceholder'),
      confirmText: $t('wf.confirm'),
      cancelText: $t('wf.cancel'),
      defaultValue: '',
      componentProps: {
        placeholder: $t('wf.commentPlaceholder'),
        type: 'textarea',
      },
    });
    comment = inputComment ?? '';
  } catch {
    logger.warn('用户取消批量转交操作');
    return; // 用户主动取消批量转交
  }
  // 步骤2：执行批量转交 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await batchTransfer(ids.map((taskId) => ({ taskId, targetUserId, comment })));
    showToast.success($t('wf.batchTransferSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('批量转交失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}

/**
 * 批量催办勾选任务的当前办理人。
 * 步骤1：确认弹窗；步骤2：调用后端 batchUrge 端点（POST /task/batchUrge 对应 FlowController）。
 */
async function handleBatchUrge() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ydszConfirm(
      $t('wf.confirmBatchUrge', { count: ids.length }),
      $t('wf.batchUrgeConfirm'),
      {
        type: 'warning',
      },
    );
  } catch (error) {
    logger.warn('用户取消批量催办操作', error);
    return; // 用户主动取消批量催办
  }
  // 步骤2：执行批量催办 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    const result = await batchUrge({}, ids);
    const successCount = result?.successCount ?? ids.length;
    showToast.success($t('wf.batchUrgeSuccess', { count: successCount }));
    gridApi.query();
  } catch (error) {
    logger.warn('批量催办失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <YdTabs v-model="activeTab" class="px-4 pt-2" @tab-change="handleTabChange">
      <YdTabsContent :label="$t('wf.myTodo')" name="todo" />
      <YdTabsContent :label="$t('wf.myDone')" name="done" />
    </YdTabs>
    <Grid :table-title="$t('wf.todoTasks')">
      <template #toolbar-tools>
        <template v-if="activeTab === 'todo'">
          <YdButtonBase variant="default" class="bg-green-600 text-white hover:bg-green-700" @click="handleBatchPass">{{
            $t('wf.batchPass')
          }}</YdButtonBase>
          <YdButtonBase variant="destructive" @click="handleBatchReject">{{
            $t('wf.batchReject')
          }}</YdButtonBase>
          <YdButtonBase variant="default" class="bg-yellow-500 text-white hover:bg-yellow-600" @click="handleBatchTransfer">{{
            $t('wf.batchTransfer')
          }}</YdButtonBase>
          <YdButtonBase variant="secondary" @click="handleBatchUrge">{{
            $t('wf.batchUrge')
          }}</YdButtonBase>
        </template>
      </template>
    </Grid>
    <TaskFormModal @success="gridApi.query()" />
    <TaskOperationModal @success="gridApi.query()" />
  </Page>
</template>
